def chkPrime1(k):                   # 2 ~ k-1 까지 나눠 보기
    count = 0                       # 나눗셈 횟수
    for v in range(2, k):
        count += 1
        if k % v == 0:
            return 0, count
    return 1, count

def chkPrime2(k):                   # 2 ~ √k 까지만 나눠 보기
    count = 0
    for v in range(2, int(k**0.5) + 1):
        count += 1
        if k % v == 0:
            return 0, count
    return 1, count

for chk in (chkPrime1, chkPrime2):
    ops = 0
    for num in range(2, 1001):
        prime, c = chk(num)
        ops = c                     # 이 수를 판정할 때 한 나눗셈 횟수
    print(chk.__name__, '나눗셈:', ops, '번')

